int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = 0;
    struct rds_atomic_args *args;

    if (cmsg->cmsg_len != CMSG_LEN(sizeof(struct rds_atomic_args)))
        return -EINVAL;

    if (rs->atomic_op_active)
        return -EBUSY;

    args = CMSG_DATA(cmsg);

    switch (args->op_type) {
        case RDS_ATOMIC_SEND:
            if (!rm->sg)
                return -ENOMEM;
            break;
        case RDS_ATOMIC_RECV:
            rm->flags |= RDS_MSG_FLAG_RECV_ATOMIC;
            break;
        default:
            return -EOPNOTSUPP;
    }

    rm->atomic_op = args->op_type;
    rm->atomic_key = args->key;

    if (args->notify) {
        rm->notifier = kzalloc(sizeof(struct rds_notifier), GFP_KERNEL);
        if (!rm->notifier)
            return -ENOMEM;
    }

    if (args->remote_addr) {
        memcpy(&rm->remote_addr, args->remote_addr, sizeof(rm->remote_addr));
    } else {
        ret = -EINVAL;
    }

    rs->atomic_op_active = 1;
    return ret;
}

int rds_atomic_msg_op(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    struct rds_atomic_args args;
    struct scatterlist *sg;
    int ret = 0;
    size_t len;

    if (cmsg->cmsg_len != CMSG_LEN(sizeof(args)))
        return -EINVAL;

    if (rm->atomic_op)
        return -EBUSY;

    memcpy(&args, CMSG_DATA(cmsg), sizeof(args));

    switch (args.type) {
    case RDS_ATOMIC_ADD:
    case RDS_ATOMIC_CMPXCHG:
        break;
    default:
        return -EINVAL;
    }

    len = args.nents * sizeof(*sg);
    sg = kmalloc(len, GFP_KERNEL);
    if (!sg)
        return -ENOMEM;

    if (args.notify) {
        rm->notifier = kzalloc(sizeof(*rm->notifier), GFP_KERNEL);
        if (!rm->notifier) {
            kfree(sg);
            return -ENOMEM;
        }
    }

    rm->atomic_op = args.type;
    rm->sg = sg;
    rm->sg_len = args.nents;
    rm->addr = args.addr;
    rm->key = args.key;

    return 0;
}

int rds_atomic_op(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg) {
    struct rds_atomic_op_args args;
    struct scatterlist *sg;
    int ret = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(args)))
        return ret;

    if (rm->atomic_op_active)
        return -EBUSY;

    memcpy(&args, CMSG_DATA(cmsg), sizeof(args));

    switch (args.op_type) {
        case RDS_ATOMIC_OP_TYPE_A:
            rm->atomic_op_type = RDS_ATOMIC_OP_TYPE_A;
            break;
        case RDS_ATOMIC_OP_TYPE_B:
            rm->atomic_op_type = RDS_ATOMIC_OP_TYPE_B;
            break;
        default:
            return ret;
    }

    sg = kzalloc(sizeof(*sg) * args.sg_len, GFP_KERNEL);
    if (!sg)
        return -ENOMEM;

    rm->atomic_sg = sg;
    rm->atomic_sg_len = args.sg_len;

    if (args.local_addr && !IS_ALIGNED((unsigned long)args.local_addr, 8))
        return -EFAULT;

    if (args.notify_enabled) {
        struct rds_notifier *n = kmalloc(sizeof(*n), GFP_KERNEL);
        if (!n) {
            ret = -ENOMEM;
            goto out_free_sg;
        }
        rm->atomic_notifier = n;
    }

    rm->atomic_remote_addr = args.remote_addr;
    rm->atomic_key = args.key;
    rm->atomic_op_active = 1;

    return 0;

out_free_sg:
    kfree(sg);
    return ret;
}

int rds_atomic_msg_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = -EINVAL;

    if (cmsg->cmsg_len < sizeof(struct rds_atomic_args))
        return ret;

    if (rm->atomic_op)
        return -EEXIST;

    struct rds_atomic_args *args = (struct rds_atomic_args *)CMSG_DATA(cmsg);
    rm->atomic_op = kmalloc(sizeof(*rm->atomic_op), GFP_KERNEL);
    if (!rm->atomic_op)
        return -ENOMEM;

    switch (args->type) {
        case RDS_ATOMIC_FADD:
        case RDS_ATOMIC_CMWPD:
            rm->atomic_op->type = args->type;
            break;
        default:
            kfree(rm->atomic_op);
            return -EINVAL;
    }

    rm->atomic_op->sg = kmalloc_array(args->nents, sizeof(*rm->atomic_op->sg), GFP_KERNEL);
    if (!rm->atomic_op->sg) {
        kfree(rm->atomic_op);
        return -ENOMEM;
    }

    rm->atomic_op->nents = args->nents;
    memcpy(rm->atomic_op->sg, args->sg, args->nents * sizeof(*rm->atomic_op->sg));

    if (!is_aligned((unsigned long)args->addr, __alignof__(u64))) {
        ret = -EADDRNOTAVAIL;
        goto out_free_sg;
    }

    rm->atomic_op->addr = args->addr;
    rm->atomic_op->key = args->key;

    if (args->notify) {
        rm->atomic_op->notify = kmalloc(sizeof(*rm->atomic_op->notify), GFP_KERNEL);
        if (!rm->atomic_op->notify) {
            ret = -ENOMEM;
            goto out_free_sg;
        }
        rm->atomic_op->notify->type = args->notify_type;
    }

    return 0;

out_free_sg:
    kfree(rm->atomic_op->sg);
    kfree(rm->atomic_op);
    return ret;
}

int rds_atomic_process_op(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
	int ret = -EINVAL;

	/* Validate control message length */
	if (cmsg->cmsg_len < CMSG_LEN(sizeof(struct rds_atomic_args)))
		goto out;

	/* Check if atomic operation is already active */
	if (rm->atomic_op)
		goto out;

	struct rds_atomic_args *args = CMSG_DATA(cmsg);
	if (args->op_type > RDS_ATOMIC_MAX)
		goto out;

	/* Allocate and setup scatter-gather list */
	struct rds_sg_list *s = kmalloc(sizeof(*s), GFP_KERNEL);
	if (!s)
		goto out;

	s->nents = args->nents;
	s->offset = args->offset;
	s->size = args->size;

	/* Check and set operation type */
	switch (args->op_type) {
	case RDS_ATOMIC_ADD:
		rm->atomic_op = rds_atomic_add;
		break;
	case RDS_ATOMIC_FETCH_AND_ADD:
		rm->atomic_op = rds_atomic_fetch_and_add;
		break;
	default:
		goto out_free_sg;
	}

	/* Verify local address alignment */
	if (rs->local_addr.s_addr && rs->local_addr.s_addr != args->local_addr) {
		ret = -EADDRNOTAVAIL;
		goto out_free_sg;
	}

	/* Setup remote address and key */
	rm->dest_addr.s_addr = args->remote_addr;
	rm->atomic_key = args->key;

	/* Allocate notifier if required */
	if (args->notify) {
		struct rds_notifier *n = kmalloc(sizeof(*n), GFP_KERNEL);
		if (!n) {
			ret = -ENOMEM;
			goto out_free_sg;
		}
		rm->notifier = n;
		n->flags = args->notify;
	}

	rm->sg = s;
	ret = 0;
out:
	return ret;

out_free_sg:
	kfree(s);
	goto out;
}
